#!/usr/bin/env bash
# 두 번째 라운드 검수 2차: Antigravity 의 시각과 애니메이션 감사(원본 빌드 대 최종 결과 빌드). 저장소 루트에서 실행.
cd "$(dirname "$0")/../.." || exit 1
PROMPT='First read migration-audit/BRIEF.md, migration-audit/MIGRATION_SPEC.md, migration-audit/MISSION.md sections 4, 5, 7 and 11, and migration-audit/motion/ANIMATION_INVENTORY.md. The founder asked for the three QA cycles to be run once more from scratch. This is cycle 2 of that SECOND round: the visual and animation audit of the RESULT build against the ORIGINAL build. Do NOT read any earlier QA report (files in migration-audit/qa, or files starting with CYCLE or R2_): this must be a fresh audit that does not lean on earlier verdicts, and it must cover what a first pass typically skips. Run every command in the foreground and wait for it; no background tasks; write your report before you end even if something could not be completed. Rules: do not modify any file under web/ or any existing document; no git commands that change anything; no next build. Create files only under migration-audit/harness/agy-r2/, migration-audit/screenshots/r2-agy/ and migration-audit/motion/r2-agy/, plus the one report migration-audit/qa/R2_CYCLE2_agy.md. Builds (static exports of the same app, served locally): ORIGINAL (baseline commit 63445c7, identical to the deployed site) at http://127.0.0.1:4175/voila-test-aresjoo/ and RESULT (final result branch) at http://127.0.0.1:4176/voila-test-aresjoo/. Playwright (Chrome) is in web/node_modules; reuse web/scripts/capture/states.mjs (makeState, installState) for seeded logged-in states and read migration-audit/harness/lib/common.mjs for determinism controls (fixed clock, fonts ready, images decoded, disable checker imaging). One thing to know about the RESULT: its confirm dialog ignores presses for 350 ms after it appears and measures that with the wall clock, so with a frozen clock advance the clock before pressing a confirm button, and with a real clock wait 600 ms; do the same on both builds. Everything is a browser-only test ledger with fake money; opening boxes and taking items in seeded states is fine; do not submit a withdrawal or a shipping request. INTENDED differences (everything else must be identical): sample reviews (review section on box detail pages, the /reviews screen, rating line and review count on home box cards, the review detail sheet, the first header link on a box page); wallet history lists opening and take transactions; negative amounts read -$1 instead of $-1; the account password sheet can complete and shows specific error lines; a withdrawal that could not be debited is listed as a $0 row marked not debited; the review write sheet keeps its draft per item. Cover in this run, on BOTH builds with identical steps: (A) widths 320, 360, 430, 768, 1024 and 1920 in ko, en and zh for every route outside the intended areas (inventory seeded, wallet-withdraw, verify, wins, guide, legal center and three legal documents, account, about, community, profile, not-found) and for the non-review regions of home and of two box pages (header, hero, search, chips, card title and price, purchase bar, contents tiles, odds summary and tables, notes, footer): compare region by region with bounding boxes within 2px, text, line counts, computed font family, size, weight, line height, color, background, radius; report every mismatch with both values. (B) The opening animation for results of different sizes: find seeded states and seeds that produce a result below the box price, above it, and a high or top result (web/lib/fairness.ts and web/lib/opening.ts show how seed, client seed and nonce give the roll; migration-audit/harness/golden/draws.json lists rolls and items for fixed seeds), then record frames every 50 ms on both builds at 390 and at 1440, normal and reduced motion, for one box and for ten boxes; compare phase order, durations, final screens, and for the larger results the light effect, the photo movement and the sound trigger calls (instrument AudioContext or HTMLAudioElement play calls and navigator.vibrate calls and compare the call lists). (C) Every hidden UI state on both builds: loading and pending states (throttle or delay to catch them), empty states, inline error lines, tooltips or title attributes, toasts, nested sheets (a sheet opened from a sheet), scroll lock and focus trap, escape and outside press, back button with a sheet open. (D) Typography and wrapping in en and zh at 320 and 360 for long names and large numbers (use KRW display and a seeded large balance): truncation, ellipsis, overflow, overlap, on both builds. (E) In the intended areas judge quality against DESIGN.md at widths 320, 360, 768 and 1920: review rows, product card, photo, rating block, more button, /reviews, wallet history rows with the new transactions, the $0 not-debited row if you can produce it, the password sheet error lines. Grade every finding P0 to P3 with the mission definitions and mark it as: unintended difference from ORIGINAL, quality problem inside an intended area, or property of ORIGINAL that is unchanged. Never claim to have seen or run something you did not; state the exact numbers of routes, widths, languages, frames and comparisons you actually ran, taken from your result files, not from your plan. Separate: seen on screen, read in code, ran myself (with the command), guess. Write in Korean, no em dash characters, no middle dot characters, no exclamation marks. Link every finding to a screenshot or frame file. End with one line giving the number of unintended differences found, and the list of what you could not run.'
rtk agy --dangerously-skip-permissions --model gemini-3.8-flash-high --effort high --print "$PROMPT" > migration-audit/logs/agy-r2-cycle2-run.log 2>&1
echo "done r2 cycle2 exit $?"
ls -la migration-audit/qa/R2_CYCLE2_agy.md 2>&1 | cut -c1-120
